import { expect, test } from '@playwright/test'
import { readFileSync } from 'node:fs'
import {
  hasNoRecordChanges,
  mergeNativeChanges,
  sameFingerprints,
  scalarSignature,
  type NativeFingerprints,
  type NativeStateChanges,
  type NativeStateNormalizers,
} from '../../src/lib/nativeStateChanges'

// Generated by state_changes::tests::frontend_fixture_matches_native_responses.
const fixture = JSON.parse(readFileSync(new URL('../fixtures/native-state-changes.json', import.meta.url), 'utf8')) as {
  before: { state: Record<string, unknown>; fingerprints: NativeFingerprints }
  changes: { changes: NativeStateChanges }
  after: Record<string, unknown>
  afterFingerprints: NativeFingerprints
}

const identity: NativeStateNormalizers = { value: (_key, value) => value, record: (_key, record) => record }

function merge(held: Record<string, unknown>, known: NativeFingerprints, changes: NativeStateChanges, normalize = identity) {
  const steps = mergeNativeChanges(held, known, changes, normalize)
  for (;;) {
    const step = steps.next()
    if (step.done) return step.value
  }
}

test('a native changes response merges into exactly the new native snapshot', () => {
  const merged = merge(fixture.before.state, fixture.before.fingerprints, fixture.changes.changes)
  expect(merged).not.toBeNull()
  expect(merged!.state).toEqual(fixture.after)
  expect(sameFingerprints(merged!.fingerprints, fixture.afterFingerprints)).toBe(true)
  // The edited, added, and reordered plans arrive; the rest keep their identity.
  const plans = merged!.state.plans as { id: string }[]
  const heldPlans = fixture.before.state.plans as { id: string }[]
  expect(plans.find(plan => plan.id === 'plan-0')).toBe(heldPlans.find(plan => plan.id === 'plan-0'))
  expect(fixture.changes.changes.collections.plans.records.map(record => (record as { id: string }).id).sort())
    .toEqual(['plan-2', 'plan-new'])
})

test('unchanged snapshots carry only scalars with the same signature', () => {
  const changes: NativeStateChanges = { values: { localSequence: 7, canRedo: false, operations: [] }, valueHashes: {}, collections: {} }
  expect(hasNoRecordChanges(changes)).toBe(true)
  expect(scalarSignature(changes.values)).toBe(scalarSignature({ operations: [], canRedo: false, localSequence: 7, plans: [] }))
  expect(scalarSignature({ ...changes.values, localSequence: 8 })).not.toBe(scalarSignature(changes.values))
})

test('changed records are normalized; unchanged records are reused without normalizing', () => {
  const held = { plans: [{ id: 'a', text: 'held' }, { id: 'b', text: 'held' }] }
  const known: NativeFingerprints = { values: {}, collections: { plans: { ids: ['a', 'b'], hashes: ['1', '2'] } } }
  const normalized: string[] = []
  const merged = merge(held, known, {
    values: {}, valueHashes: {},
    collections: { plans: { ids: ['b', 'a'], records: [{ id: 'b', text: 'native' }], hashes: ['3'] } },
  }, { value: (_key, value) => value, record: (_key, record) => {
    normalized.push((record as { id: string }).id)
    return { ...(record as object), normalized: true }
  } })
  expect(normalized).toEqual(['b'])
  expect(merged!.state.plans).toEqual([{ id: 'b', text: 'native', normalized: true }, held.plans[0]])
  expect((merged!.state.plans as unknown[])[1]).toBe(held.plans[0])
  expect(merged!.fingerprints.collections.plans).toEqual({ ids: ['b', 'a'], hashes: ['3', '1'] })
})

test('a held state missing an unchanged record asks for a complete read', () => {
  const known: NativeFingerprints = { values: {}, collections: { plans: { ids: ['a', 'b'], hashes: ['1', '2'] } } }
  const changes: NativeStateChanges = {
    values: {}, valueHashes: {},
    collections: { plans: { ids: ['a', 'b', 'c'], records: [{ id: 'c' }], hashes: ['3'] } },
  }
  expect(merge({ plans: [{ id: 'a' }] }, known, changes)).toBeNull()
  expect(merge({ plans: [{ id: 'a' }, { id: 'b' }] }, { values: {}, collections: {} }, changes)).toBeNull()
})

test('collections switch between keyed and whole fingerprints', () => {
  const keyed: NativeFingerprints = { values: {}, collections: { notes: { ids: ['a'], hashes: ['1'] } } }
  const toWhole = merge({ notes: [{ id: 'a' }] }, keyed, {
    values: { notes: [{ id: 'a' }, { id: 'a' }] }, valueHashes: { notes: 'w' }, collections: {},
  })!
  expect(toWhole.fingerprints).toEqual({ values: { notes: 'w' }, collections: {} })
  const backToKeyed = merge(toWhole.state, toWhole.fingerprints, {
    values: {}, valueHashes: {}, collections: { notes: { ids: ['b'], records: [{ id: 'b' }], hashes: ['2'] } },
  })!
  expect(backToKeyed.state.notes).toEqual([{ id: 'b' }])
  expect(backToKeyed.fingerprints).toEqual({ values: {}, collections: { notes: { ids: ['b'], hashes: ['2'] } } })
})
